# Step A: fetch friends & roommates from phone contacts

pw_list = apis.supervisor.show_account_passwords()
phone_pw = [a['password'] for a in pw_list if a['account_name']=='phone'][0]
phone_number='2307354647'
phone_token = apis.phone.login(username=phone_number, password=phone_pw)['access_token']

page_limit=20
page_index=0
all_contacts=[]
while True:
    resp = apis.phone.search_contacts(access_token=phone_token, query='', page_index=page_index, page_limit=page_limit)
    if not resp:
        break
    all_contacts.extend(resp)
    page_index += 1
    if page_index > 200:
        break

from collections import Counter
rel_counter=Counter()
for c in all_contacts:
    for rel in (c.get('relationships') or []):
        rel_counter[str(rel).strip().lower()] += 1

friend_terms={'friend','friends'}
roommate_terms={'roommate','roommates'}

def is_friend_or_roommate(c):
    for rel in (c.get('relationships') or []):
        rl=str(rel).strip().lower()
        if rl in friend_terms or rl in roommate_terms:
            return True
    return False

friends_roommates=[c for c in all_contacts if is_friend_or_roommate(c)]

print('total_phone_contacts:', len(all_contacts))
print('top_relationships:', rel_counter.most_common(10))
print('friends+roommates_count:', len(friends_roommates))
print('friends+roommates_contacts (name, email, rels):')
for c in friends_roommates:
    print({'first_name': c.get('first_name'), 'last_name': c.get('last_name'), 'email': c.get('email'), 'phone': c.get('phone_number'), 'relationships': c.get('relationships')})

